package com.digiaudit.grcpc.modules.masterdata.catalog.regulation.api;
import com.digiaudit.grcpc.modules.masterdata.catalog.regulation.api.dto.CentralRegulationDtos;import com.digiaudit.grcpc.modules.masterdata.catalog.regulation.application.*;import com.digiaudit.grcpc.modules.masterdata.catalog.shared.api.dto.CatalogLifecycleCommandRequest;import com.digiaudit.grcpc.modules.masterdata.shared.api.dto.*;import jakarta.validation.Valid;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/master-data/central/regulations") public class CentralRegulationController{private final CentralRegulationCommandService commands;private final CentralRegulationQueryService queries;public CentralRegulationController(CentralRegulationCommandService c,CentralRegulationQueryService q){commands=c;queries=q;}@GetMapping @PreAuthorize("hasAuthority('CENTRAL_REGULATION_VIEW') or hasAuthority('ROLE_ROOT_ADMIN')") public List<CentralRegulationDtos.Summary> list(@RequestParam(required=false)UUID groupId){return queries.regulations(groupId);}@GetMapping("/deleted") @PreAuthorize("hasAuthority('CENTRAL_REGULATION_VIEW') or hasAuthority('ROLE_ROOT_ADMIN')") public List<CentralRegulationDtos.Summary> deleted(){return queries.deletedRegulations();}@GetMapping("/{id}") @PreAuthorize("hasAuthority('CENTRAL_REGULATION_VIEW') or hasAuthority('ROLE_ROOT_ADMIN')") public CentralRegulationDtos.Detail detail(@PathVariable UUID id){return queries.regulation(id);}@PostMapping @PreAuthorize("hasAuthority('CENTRAL_REGULATION_CREATE') or hasAuthority('ROLE_ROOT_ADMIN')") public MasterDataAggregateMutationResponse create(@Valid @RequestBody CentralRegulationDtos.CreateRegulation r){return commands.create(r);}@PatchMapping("/{id}") @PreAuthorize("hasAuthority('CENTRAL_REGULATION_UPDATE') or hasAuthority('ROLE_ROOT_ADMIN')") public MasterDataAggregateMutationResponse update(@PathVariable UUID id,@Valid @RequestBody CentralRegulationDtos.Update r){return commands.update(id,r);}@PostMapping("/{id}/move") @PreAuthorize("hasAuthority('CENTRAL_REGULATION_MOVE') or hasAuthority('ROLE_ROOT_ADMIN')") public MasterDataRevisionMutationResponse move(@PathVariable UUID id,@Valid @RequestBody CentralRegulationDtos.MoveRegulation r){return commands.move(id,r);}@PostMapping("/{id}/activate") @PreAuthorize("hasAuthority('CENTRAL_REGULATION_LIFECYCLE') or hasAuthority('ROLE_ROOT_ADMIN')") public MasterDataRevisionMutationResponse activate(@PathVariable UUID id,@Valid @RequestBody CatalogLifecycleCommandRequest r){return commands.activate(id,r.version());}@PostMapping("/{id}/inactivate") @PreAuthorize("hasAuthority('CENTRAL_REGULATION_LIFECYCLE') or hasAuthority('ROLE_ROOT_ADMIN')") public MasterDataRevisionMutationResponse inactivate(@PathVariable UUID id,@Valid @RequestBody CatalogLifecycleCommandRequest r){return commands.inactivate(id,r.version());}@PostMapping("/{id}/delete") @PreAuthorize("hasAuthority('CENTRAL_REGULATION_DELETE') or hasAuthority('ROLE_ROOT_ADMIN')") public MasterDataRevisionMutationResponse delete(@PathVariable UUID id,@Valid @RequestBody CatalogLifecycleCommandRequest r){return commands.delete(id,r.version());}@PostMapping("/{id}/restore") @PreAuthorize("hasAuthority('CENTRAL_REGULATION_RESTORE') or hasAuthority('ROLE_ROOT_ADMIN')") public MasterDataRevisionMutationResponse restore(@PathVariable UUID id,@Valid @RequestBody CatalogLifecycleCommandRequest r){return commands.restore(id,r.version());}}
